"use client";

import { cva } from "class-variance-authority";
import {
  type InputHTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
  useRef,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { useControllableState } from "@/hooks/use-controllable-state";
import { useFormReset } from "@/hooks/use-form-reset";
import { FOCUS_OUTLINE } from "@/lib/focus-outline";
import { inputSizeClasses } from "@/lib/input-variants";
import { cn } from "@/lib/utils";

// Sizes come from the shared input grid so a SearchInput lines up with an Input
// or InputGroup of the same nominal size; focus and invalid mirror InputGroup's
// inset grammar on --ring / --error.
const searchInputVariants = cva(
  // The shell owns the focus indicator for the bare input inside it. Under forced-colors
  // the ring (a box-shadow) is dropped and border-color is forced to the system palette,
  // so the shell draws an outline of its own there — see input-variants.ts.
  "relative flex items-center gap-2 bg-background border border-border font-mono shrink-0 transition-colors motion-reduce:transition-none focus-within:border-ring focus-within:ring-1 focus-within:ring-ring focus-within:forced-colors:outline-2 focus-within:forced-colors:outline-offset-2 has-[input[aria-invalid=true]]:border-error has-[input[aria-invalid=true]]:ring-1 has-[input[aria-invalid=true]]:ring-error has-[input[aria-invalid=true]]:focus-within:border-error has-[input[aria-invalid=true]]:focus-within:ring-error",
  {
    variants: {
      size: inputSizeClasses,
      disabled: {
        true: "opacity-50 border-dashed pointer-events-none",
      },
    },
    defaultVariants: { size: "md" },
  },
);

const defaultPrefix = (
  <span className="text-foreground font-bold" aria-hidden="true">
    /
  </span>
);

export interface SearchInputProps
  extends Omit<
    InputHTMLAttributes<HTMLInputElement>,
    "value" | "defaultValue" | "onChange" | "type" | "size" | "prefix"
  > {
  /** Controlled search value. */
  value?: string;
  /** Initial search value for uncontrolled usage. */
  defaultValue?: string;
  /** Called with the next search value when the native input changes. */
  onChange?: (value: string) => void;
  /** Called when Escape is pressed and the event was not already handled. */
  onEscape?: () => void;
  /** Called when Enter is pressed and the event was not already handled. */
  onEnter?: () => void;
  /** Prefix content before the input. Pass null to hide it. */
  prefix?: ReactNode;
  /** Accessible name for the clear button shown while the input has a value. */
  clearLabel?: string;
  /** Height/padding/font size token, shared with Input and InputGroup. */
  size?: "sm" | "md" | "lg";
  /**
   * Classes merged onto the inner input. The public seam for styling the field itself (text
   * overflow, alignment) instead of reaching through the shell with a `[&_input]` selector.
   */
  inputClassName?: string;
  /** Ref forwarded to the underlying element. */
  ref?: Ref<HTMLInputElement>;
}

/**
 * Terminal-styled search input with / prefix and keyboard event callbacks. Supports controlled
 * and uncontrolled modes.
 */
export function SearchInput({
  value,
  defaultValue,
  onChange,
  onEscape,
  onEnter,
  onKeyDown,
  placeholder = "Search...",
  prefix = defaultPrefix,
  clearLabel = "Clear search",
  className,
  inputClassName,
  ref,
  size,
  disabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  id,
  ...rest
}: SearchInputProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const composedRef = useComposedRefs(inputRef, ref);
  const [current, setValue, , resetValue] = useControllableState({
    value,
    defaultValue: defaultValue ?? "",
    onChange,
  });
  const invalidatePendingReset = useFormReset(
    inputRef,
    defaultValue ?? "",
    resetValue,
    value === undefined,
  );

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    if (e.nativeEvent.isComposing || e.nativeEvent.keyCode === 229) return;

    if (e.key === "Escape") {
      // Only consume Escape when it does something: clear a non-empty value, or
      // call onEscape. An untouched Escape on an empty input must propagate so the
      // native search clear and a wrapping <dialog> cancel still work.
      if (current.length > 0) {
        e.preventDefault();
        invalidatePendingReset();
        setValue("");
      } else if (onEscape) {
        e.preventDefault();
        onEscape();
      }
    } else if (e.key === "Enter" && onEnter) {
      e.preventDefault();
      onEnter();
    }
  };

  return (
    <div
      data-slot="search-input"
      className={cn(searchInputVariants({ size, disabled }), className)}
    >
      {prefix}
      <input
        ref={composedRef}
        data-slot="search-input-control"
        type="search"
        value={current}
        onChange={(e) => {
          invalidatePendingReset();
          setValue(e.target.value);
        }}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        id={id}
        aria-label={ariaLabel ?? (!id && !ariaLabelledBy ? placeholder : undefined)}
        aria-labelledby={ariaLabelledBy}
        disabled={disabled}
        {...rest}
        className={cn(
          "min-w-0 flex-1 bg-transparent pr-6 font-mono text-foreground placeholder:text-foreground/55 focus:outline-none disabled:cursor-not-allowed pointer-coarse:pr-9 [&::-webkit-search-cancel-button]:appearance-none",
          inputClassName,
        )}
      />
      {current.length > 0 ? (
        <button
          type="button"
          data-slot="search-input-clear"
          aria-label={clearLabel}
          disabled={disabled}
          className={`absolute right-2 top-1/2 grid size-6 -translate-y-1/2 place-items-center text-base leading-none text-foreground/70 hover:text-foreground ${FOCUS_OUTLINE} disabled:cursor-not-allowed pointer-coarse:right-0 pointer-coarse:size-11`}
          onPointerDown={(event) => event.preventDefault()}
          onClick={() => {
            invalidatePendingReset();
            setValue("");
            inputRef.current?.focus();
          }}
        >
          <span aria-hidden="true">×</span>
        </button>
      ) : null}
    </div>
  );
}
